35	// writeDiskFile 手工写入一份数据文件，便于构造正常流程不会产生的损坏记录。
36	func writeDiskFile(t *testing.T, dir string, st diskState) {
37		t.Helper()
38		data, err := json.MarshalIndent(st, "", "  ")
39		if err != nil {
40			t.Fatalf("marshal data file: %v", err)
41		}
42		if err := os.WriteFile(filepath.Join(dir, "water-data.json"), data, 0o644); err != nil {
43			t.Fatalf("write data file: %v", err)
44		}
45	}
