67	// assertOpenRejects 断言打开整次失败：返回 nil 存放、错误可识别为
68	// ErrCorruptRecord，且信息包含出问题的样品编号与项目（noItem 为 true 时
69	// 只要求编号），原文件字节不被改动。
70	func assertOpenRejects(t *testing.T, dir, sampleID, itemHint string, noItem bool) {
71		t.Helper()
72		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
73		if err != nil {
74			t.Fatalf("read file before open: %v", err)
75		}
76		got, err := Open(dir)
77		if err == nil {
78			if got != nil {
79				got.Close()
80			}
81			t.Fatalf("损坏数据必须让整次 Open 失败，sample=%s", sampleID)
82		}
83		if got != nil {
84			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
85		}
86		if !errors.Is(err, ErrCorruptRecord) {
87			t.Fatalf("应返回 ErrCorruptRecord，got %v", err)
88		}
89		msg := err.Error()
90		if !strings.Contains(msg, sampleID) {
91			t.Fatalf("错误信息应指出样品编号 %q，实际 %q", sampleID, msg)
92		}
93		if !noItem && itemHint != "" && !strings.Contains(msg, itemHint) {
94			t.Fatalf("错误信息应指出项目 %q，实际 %q", itemHint, msg)
95		}
96		after, rerr := os.ReadFile(filepath.Join(dir, "water-data.json"))
97		if rerr != nil {
98			t.Fatalf("read file after open: %v", rerr)
99		}
100		if string(after) != string(before) {
101			t.Fatalf("打开失败不得覆盖或改写原数据文件")
102		}
103	}
